Nothing like it exists in the repo and there's no retry dependency, so here's a stdlib-only version:

```python
import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,)):
    """Call fn(), retrying on `exceptions` with exponential backoff and full jitter."""
    for attempt in range(attempts):
        try:
            return fn()
        except exceptions:
            if attempt == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** attempt)))


if __name__ == "__main__":
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise ValueError("not yet")
        return "ok"

    assert retry(flaky, base=0.001) == "ok" and len(calls) == 3
    try:
        retry(lambda: 1 / 0, attempts=2, base=0.001)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError("should re-raise after the last attempt")
```

